            },
            {
              "badge": "POST",
              "kind": "page",
              "label": "Create an ingest key",
              "pageId": "openapi:reference/ingest-keys/create-ingest-key.mdx",
              "route": "/docs/reference/ingest-keys/create-ingest-key"
