            {
              "badge": "DELETE",
              "kind": "page",
              "label": "Revoke an ingest key",
              "pageId": "openapi:reference/ingest-keys/revoke-ingest-key.mdx",
              "route": "/docs/reference/ingest-keys/revoke-ingest-key"
            }
          ],
          "display": "flat",
          "kind": "group",
          "label": "Ingest keys",
          "path": "/docs/reference/ingest-keys"
        },
        {
          "children": [
            {
              "badge": "POST",
              "kind": "page",
              "label": "Ingest Pyroscope profiles at the server root",
              "pageId": "openapi:reference/pyroscope-ingest/ingest-pyroscope-root.mdx",
              "route": "/docs/reference/pyroscope-ingest/ingest-pyroscope-root"
            },
            {
              "badge": "POST",
              "kind": "page",
              "label": "Ingest Pyroscope profiles",
