              "route": "/docs/reference/pyroscope-ingest/ingest-pyroscope"
            },
            {
              "badge": "POST",
              "kind": "page",
              "label": "Ingest Pyroscope profiles at the /ingest/pyroscope alias",
              "pageId": "openapi:reference/pyroscope-ingest/ingest-pyroscope-alias.mdx",
              "route": "/docs/reference/pyroscope-ingest/ingest-pyroscope-alias"
            },
            {
              "badge": "POST",
              "kind": "page",
              "label": "Ingest Pyroscope profiles over the Push API",
              "pageId": "openapi:reference/pyroscope-ingest/ingest-pyroscope-push.mdx",
              "route": "/docs/reference/pyroscope-ingest/ingest-pyroscope-push"
            }
          ],
          "display": "flat",
          "kind": "group",
          "label": "Pyroscope ingest",
          "path": "/docs/reference/pyroscope-ingest"
        }
      ],
      "display": "flat",
      "kind": "group",
      "label": "Reference",
      "path": "/docs/reference",
      "route": "/docs/reference"
    },
    {
      "children": [
        {
          "description": "What each sigiro_* table stores and how to query the machine that emitted the telemetry.",
          "kind": "page",
          "label": "About the telemetry tables",
          "pageId": "filesystem:explanation/tables.md",
          "route": "/docs/explanation/tables"
        },
        {
          "description": "Historical design note; use bounded raw telemetry queries for active analysis.",
